// confirmation in between.
func TestTheCommandOpensTheDocumentationOnce(t *testing.T) {
	tests := []struct {
		name    string
		openErr error
	}{
		{"the opener succeeds", nil},
		{"the opener fails", errors.New(`exec: "xdg-open": executable file not found in $PATH`)},
	}

