	a := router(t, about.New(testConfig()))

	if cmd := feedKey(t, a, testutil.Key(keymap.Web)); cmd == nil {
		t.Fatalf("%q on the About screen produced no command: the router swallowed it or the screen ignored it", keymap.Web)
	}
}

